drills.solution:
const changed = (prev, next) => prev.length !== next.length || next.some((d, i) => !Object.is(d, prev[i]));

export function createEffectSlot() {
  let prevDeps;
  let mounted = false;
  let cleanup;
  const runCleanup = () => {
    const c = cleanup;
    cleanup = undefined;
    if (typeof c === 'function') c();
  };
  return {
    render(effect, deps) {
      const run = !mounted || deps === undefined || prevDeps === undefined || changed(prevDeps, deps);
      mounted = true;
      if (!run) return false;
      runCleanup();
      prevDeps = deps;
      cleanup = effect();
      return true;
    },
    unmount() {
      runCleanup();
    },
  };
}

tests.code:
assert.equal(typeof mod.createEffectSlot, 'function', 'export createEffectSlot');
const slot = mod.createEffectSlot();
let runs = 0;
const fx = () => { runs++; };
assert.equal(slot.render(fx, [1]), true);
assert.equal(slot.render(fx, [1]), false);
assert.equal(slot.render(fx, [2]), true);
assert.equal(runs, 2);

const slot = mod.createEffectSlot();
const log = [];
const fx = (n) => () => { log.push('run ' + n); return () => log.push('cleanup ' + n); };
slot.render(fx(1), ['a']);
slot.render(fx(2), ['b']);
slot.unmount();
assert.deepEqual(log, ['run 1', 'cleanup 1', 'run 2', 'cleanup 2']);

const once = mod.createEffectSlot();
let a = 0;
once.render(() => { a++; }, []);
once.render(() => { a++; }, []);
assert.equal(a, 1);
const every = mod.createEffectSlot();
let b = 0;
every.render(() => { b++; });
every.render(() => { b++; });
assert.equal(b, 2);

const slot = mod.createEffectSlot();
let runs = 0;
const fx = () => { runs++; };
slot.render(fx, [NaN]);
assert.equal(slot.render(fx, [NaN]), false, 'NaN is stable');
assert.equal(slot.render(fx, [{}]), true);
assert.equal(slot.render(fx, [{}]), true, 'a new object is a change');
const o = {};
slot.render(fx, [o]);
assert.equal(slot.render(fx, [o]), false);

const slot = mod.createEffectSlot();
slot.render(() => {}, [1]);
assert.equal(slot.render(() => {}, [1, 2]), true);

const slot = mod.createEffectSlot();
let cleaned = 0;
slot.render(() => () => { cleaned++; }, []);
slot.unmount();
slot.unmount();
assert.equal(cleaned, 1);
const none = mod.createEffectSlot();
none.unmount();

drills.explanation:
Decide whether to run, then clean up the previous run, then run and store the new cleanup:

```js
render(effect, deps) {
  const run = !mounted || deps === undefined || prevDeps === undefined || changed(prevDeps, deps);
  mounted = true;
  if (!run) return false;
  runCleanup();
  prevDeps = deps;
  cleanup = effect();
  return true;
}
```

`changed` compares lengths and then every element with `Object.is`, which is why `NaN` is stable while a fresh `{}` always re-runs: exactly the behaviour behind the "object in deps" infinite loop.
